316 |     /// @param _to Address of the receiver
317 |     function withdrawCollateral(address _vault, address _to) external {
318 |         // Reverts if vault is not registered
319 |         (address token, uint256 id) = _verifyVault(_vault);
320 |         // Reverts if token balance is insufficient
321 |         uint256 balance = pendingBalances[_vault][_to];
322 |         if (balance == 0) revert NotEnoughTokens();
323 | 
324 |         // Resets collateral balance amount
325 |         pendingBalances[_vault][_to] = 0;
326 | 
327 |         // Transfers collateral amount to receiver
328 |         IERC1155(token).safeTransferFrom(address(this), _to, id, balance, "");
329 | 
330 |         // Emits event for withdrawing collateral balance
331 |         emit WithdrawCollateral(_vault, _to, balance);
332 |     }
